<?php

declare(strict_types=1);

namespace DDD\Domain\AI\Entities\MediaItems;

/**
 * How AI took part in making an image: generated by AI, edited by AI, or not AI. The EU AI Act label of a published
 * image is decided on it.
 *
 * Its own type in Common: the label policy and the image stamper live in Common and know no post, and "not AI" also
 * names images that never passed through the Media Manager — an upload, an Unsplash pick, a platform import. A post
 * image records the kind in its settings when it is created.
 */
class AIImageKind
{
    /** @var string An AI model produced the image */
    public const string GENERATED = 'GENERATED';

    /** @var string The image is the customer's own photo, changed with an AI editor */
    public const string EDITED = 'EDITED';

    /** @var string No AI produced or changed the image */
    public const string NOT_AI = 'NOT_AI';

    /** @var string[] Every AI image kind */
    public const array ALL_KINDS = [
        self::GENERATED,
        self::EDITED,
        self::NOT_AI,
    ];

    /**
     * Whether $aiImageKind is one of {@see self::ALL_KINDS}; null and any other string are not.
     *
     * @param string|null $aiImageKind
     *
     * @return bool
     */
    public static function isKnownAIImageKind(?string $aiImageKind): bool
    {
        return in_array($aiImageKind, self::ALL_KINDS, true);
    }
}
